package com.university.scheduler.ui;
import com.university.scheduler.dao.UiRepository;import com.university.scheduler.model.Day;import com.university.scheduler.model.PeriodType;import javafx.collections.*;import javafx.geometry.*;import javafx.scene.Parent;import javafx.scene.control.*;import javafx.scene.layout.*;
public class TimetableView{
 private final ObservableList<String[]> rows=FXCollections.observableArrayList();private final TableView<String[]> table=new TableView<>();
 public Parent getView(){VBox root=UiSupport.page("Timetable Management","View the official weekly university timetable reconstructed from the July–December 2026 Excel workbook, or manage additional scheduled sessions.");Button add=new Button("+ Add Class"),refresh=new Button("Refresh");add.getStyleClass().add("primary-button");HBox bar=new HBox(10,refresh,add);bar.setAlignment(Pos.CENTER_RIGHT);table.getColumns().addAll(col("ID",0),col("Section",1),col("Course",2),col("Course Name",3),col("Faculty ID",4),col("Faculty",5),col("Room",6),col("Day",7),col("Period",8),col("Start",9));TableColumn<String[],Void> act=new TableColumn<>("Actions");act.setCellFactory(c->new TableCell<>(){Button del=new Button("Delete");{del.setOnAction(e->{String[] r=getTableView().getItems().get(getIndex());if(UiSupport.confirm("Delete scheduled booking #"+r[0]+"?"))try{UiRepository.deleteBooking(Long.parseLong(r[0]));load();}catch(Exception ex){UiSupport.error("Could not delete booking",ex);}});}protected void updateItem(Void v,boolean empty){super.updateItem(v,empty);setGraphic(empty?null:del);}});table.getColumns().add(act);UiSupport.style(table);table.setItems(rows);add.setOnAction(e->dialog());refresh.setOnAction(e->load());VBox bookingPane=new VBox(10,bar,table);VBox.setVgrow(table,Priority.ALWAYS);Tab weekly=new Tab("Weekly Timetable",new WeeklyTimetableView().getView());Tab managed=new Tab("Booking Manager",bookingPane);weekly.setClosable(false);managed.setClosable(false);TabPane tabs=new TabPane(weekly,managed);VBox.setVgrow(tabs,Priority.ALWAYS);root.getChildren().add(tabs);load();return root;}
 private TableColumn<String[],String> col(String name,int i){return UiSupport.col(name,r->r[i]);}
 private void load(){try{rows.setAll(UiRepository.bookings());}catch(Exception e){UiSupport.error("Could not load timetable",e);}}
 private void dialog(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Add Scheduled Class");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);TextField section=UiSupport.field("Section code e.g. 1A2A"),course=UiSupport.field("Base course code"),faculty=UiSupport.field("Faculty ID"),room=UiSupport.field("Room ID"),period=UiSupport.field("Period number");ComboBox<PeriodType> type=new ComboBox<>(FXCollections.observableArrayList(PeriodType.values()));type.setValue(PeriodType.LECTURE);ComboBox<Day> day=new ComboBox<>(FXCollections.observableArrayList(Day.values()));day.setValue(Day.MONDAY);GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);g.addRow(0,new Label("Section"),section);g.addRow(1,new Label("Course code"),course);g.addRow(2,new Label("Period type"),type);g.addRow(3,new Label("Faculty ID"),faculty);g.addRow(4,new Label("Room ID"),room);g.addRow(5,new Label("Day"),day);g.addRow(6,new Label("Period"),period);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(b->{if(b==save)try{int p=Integer.parseInt(period.getText().trim());if(p<1)throw new IllegalArgumentException("Period must be positive.");UiRepository.addBooking(section.getText().trim(),course.getText().trim(),type.getValue().name(),faculty.getText().trim(),room.getText().trim(),day.getValue().name(),p);load();}catch(Exception ex){UiSupport.error("Could not add scheduled class",ex);}});}
}
